// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address initialOwner, address newOwner, address caller) public {
        vm.assume(initialOwner != address(0) && newOwner != address(0) && newOwner != initialOwner);
        // Set initial owner
        vm.prank(address(0)); // assuming initial owner is address(0) after deploy; we need to set it
        // Actually, we can transfer ownership to initialOwner first
        vm.prank(c.owner());
        c.transferOwnership(initialOwner);

        // Now caller = initialOwner tries to transfer to newOwner
        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        // After the call, owner should be newOwner
        assertTrue(c.owner() == newOwner);
    }
}

