pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address initialOwner, address newOwner, address caller) public {
        vm.assume(initialOwner != address(0) && newOwner != address(0) && newOwner != initialOwner);
        vm.prank(address(0));
        vm.prank(c.owner());
        c.transferOwnership(initialOwner);

        vm.prank(initialOwner);
        c.transferOwnership(newOwner);

        assertTrue(c.owner() == newOwner);
    }
}
